const svg=`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 440 245"><rect width="440" height="245" fill="${b}"/><ellipse cx="220" cy="111" rx="135" ry="89" fill="white" stroke="${a}" stroke-width="12"/><ellipse cx="214" cy="110" rx="103" ry="64" fill="${a}"/><ellipse cx="193" cy="91" rx="39" ry="25" fill="#DB916C"/><circle cx="254" cy="107" r="35" fill="#84AB8A"/><circle cx="218" cy="140" r="26" fill="#F8E5AC"/><rect y="185" width="440" height="60" fill="#1E4838"/><text x="220" y="209" fill="white" text-anchor="middle" font-family="Arial" font-size="15">${safe(labels[0]||r.meal)}</text><text x="220" y="230" fill="#D8EEDF" text-anchor="middle" font-family="Arial" font-size="13">${safe(labels.slice(1).join(' • '))}</text></svg>`;
